/**
 * Dependency Registry — answers "what depends on this resource?" Primary
 * source as of Roadmap #46 (owner, 2026-08-04, "ยกเลิกการใช้ hand-maintained
 * seed graph เป็นแหล่งข้อมูลหลัก"): registry/auto-dependency-graph.json,
 * regenerated by engines/workspace/dependencyDiscovery/generate.ts from 9
 * real scanners (TS imports, JSON registries, commands, LaunchAgents,
 * Docker, AI models, Supabase functions, config refs, workflows) — every
 * edge carries real evidence + a confidence score, nothing guessed.
 *
 * registry/infra-dependency-graph.json (the old hand-maintained seed) is
 * kept as a fallback, NOT deleted, per explicit owner instruction: "ห้ามลบ
 * Seed Graph จนกว่าผลลัพธ์อัตโนมัติจะผ่านการตรวจสอบ". A real diff (see
 * dependencyDiscovery/diff.ts) found several seed edges the auto scanner
 * doesn't yet match byte-for-byte (e.g. seed assumes local-runtime/*.mjs
 * repo-relative paths, but the real installed plists for the older watchers
 * point to a deployed copy at ~/dna-os-ollama/ — a genuine infra-drift
 * finding, not a scanner bug) — so both sources are still consulted here
 * until that gap is resolved.
 *
 * registry/architecture-book.json is no longer read directly here — the
 * auto graph's typescript_imports scanner already wraps it with evidence.
 */
import { readFileSync, existsSync } from "fs";
import { join } from "path";
import type { DependencyEdge, DependencyImpact } from "@/core/shared/types";

const ROOT = join(__dirname, "../..");

function readJSON<T>(relPath: string): T {
  return JSON.parse(readFileSync(join(ROOT, relPath), "utf-8"));
}

export function getDependents(resourcePath: string): DependencyEdge[] {
  const edges: DependencyEdge[] = [];
  const seen = new Set<string>();

  const autoPath = "registry/auto-dependency-graph.json";
  if (existsSync(join(ROOT, autoPath))) {
    const auto = readJSON<{ edges: DependencyEdge[] }>(autoPath);
    for (const e of auto.edges) {
      if (e.target.endsWith(resourcePath) || e.target === resourcePath || e.target === `module:${resourcePath}`) {
        const key = `${e.source}=>${e.target}`;
        if (seen.has(key)) continue;
        seen.add(key);
        edges.push(e);
      }
    }
  }

  const infraGraph = readJSON<{ edges: { source: string; target: string; label: string; kind: string }[] }>("registry/infra-dependency-graph.json");
  for (const e of infraGraph.edges) {
    if (e.target.endsWith(resourcePath) || e.target === resourcePath) {
      const key = `${e.source}=>${e.target}`;
      if (seen.has(key)) continue;
      seen.add(key);
      edges.push({ source: e.source, target: e.target, kind: e.kind as DependencyEdge["kind"], source_generated: "infra-dependency-graph" });
    }
  }

  return edges;
}

export function analyzeImpact(resourcePath: string): DependencyImpact {
  const dependents = getDependents(resourcePath);
  return {
    resource_path: resourcePath,
    dependents,
    dependency_count: dependents.length,
    safe_to_migrate: dependents.length === 0,
  };
}
